'use strict';
(()=>{
 const launch=document.createElement('button');launch.className='assistant-launch';launch.textContent='✚ Ask the clinic guide';launch.setAttribute('aria-expanded','false');launch.setAttribute('aria-controls','clinic-assistant');
 const panel=document.createElement('section');panel.id='clinic-assistant';panel.className='assistant-panel';panel.hidden=true;panel.setAttribute('role','region');panel.setAttribute('aria-label','Clinic information assistant');
 panel.innerHTML='<div class="assistant-head"><h2>Clinic guide</h2><button type="button" aria-label="Close clinic guide">×</button></div><p>Ask about services, hours, fees or finding us. For personal medical questions, please speak with a clinician.</p><div class="assistant-chips"><button type="button">Opening hours</button><button type="button">Consultation fees</button><button type="button">Our services</button><button type="button">Find the clinic</button></div><form><label for="clinic-question">Your question</label><textarea id="clinic-question" maxlength="800" required placeholder="For example: How do I arrange a visit?"></textarea><label class="assistant-consent" hidden><input type="checkbox"><span>Use AI: I agree to send this question to OpenAI. I will not include sensitive personal or medical information.</span></label><button class="button" type="submit">Ask question ↗</button></form><p class="assistant-mode" role="status">Clinic guide · answers from published clinic information</p><div class="assistant-answer" role="status" aria-live="polite">Hello. How can I help you find information about our clinic?</div><div class="assistant-links"><a href="./index.html#appointment">Request a visit</a><a href="./health.html">Health hub</a><a href="tel:+18766695974">Call the clinic</a></div><p class="fine">Not an emergency service. For urgent medical help, contact local emergency services or your nearest emergency department. <a href="./index.html#privacy">Privacy</a></p>';
 document.body.append(launch,panel);
 const close=panel.querySelector('.assistant-head button'),question=panel.querySelector('textarea'),form=panel.querySelector('form'),answer=panel.querySelector('.assistant-answer'),mode=panel.querySelector('.assistant-mode'),consent=panel.querySelector('.assistant-consent'),checkbox=consent.querySelector('input'),submit=panel.querySelector('[type=submit]');
 function setOpen(open){panel.hidden=!open;launch.setAttribute('aria-expanded',String(open));if(open)question.focus();else launch.focus();}
 launch.addEventListener('click',()=>setOpen(panel.hidden));close.addEventListener('click',()=>setOpen(false));panel.addEventListener('keydown',e=>{if(e.key==='Escape')setOpen(false);});
 const api=window.HCMC_CONFIG?.apiBase;let aiReady=false,sessionId=crypto.randomUUID();
 if(api)fetch(api+'/api/public/config',{signal:AbortSignal.timeout(8000)}).then(r=>r.json()).then(c=>{aiReady=c.assistantEnabled===true;consent.hidden=!aiReady;}).catch(()=>{});
 function guide(q){
  if(/chest pain|breath|unconscious|stroke|bleeding|suicid|self.harm|overdose|emergency/i.test(q))return 'For a possible medical emergency, seek immediate help through local emergency services or the nearest emergency department. Do not wait for this website. This guide cannot assess symptoms or provide emergency care.';
  if(/symptom|dose|diagnos|prescri|treat my|pain|medication|medicine|sick|fever|pregnan/i.test(q))return 'A clinician needs to advise on your personal health concern. I cannot diagnose, interpret results or recommend medicines. Please call +1 876 669 5974 to arrange a consultation. For general health resources, visit our Health hub.';
  const replies=[];
  if(/hour|open|clos|satur|monday|friday|sunday|time/i.test(q))replies.push('Monday–Friday: 8:30 AM–6:00 PM. Saturday: 9:30 AM–3:00 PM. All times are Jamaica time. Sunday and public holiday arrangements have not been confirmed; please telephone the clinic.');
  if(/fee|cost|price|money|pay|expens/i.test(q))replies.push('General doctor consultations start at JA$3,000. Other services, investigations and treatments may have different fees. Please contact the clinic to confirm your total and payment options.');
  if(/where|address|location|find|direction|map|park/i.test(q))replies.push('Find us at 58 Barnett Street, Montego Bay, St. James. Use Find us on the home page for the map and directions. Call +1 876 669 5974 for entrance or accessibility enquiries.');
  if(/service|special|diabet|women|screen|blood|school|home visit|cancer|gynaec|eye/i.test(q))replies.push('Our published services include general practice, diabetes care, women’s health, health screening, blood-test enquiries, occupational health, school medicals, home visits and outreach. Specialist services and home visits require confirmation of availability.');
  if(/book|appoint|visit|walk.in|schedule/i.test(q))replies.push('Use Request a visit on the home page or call +1 876 669 5974. A request is not a confirmed booking: our team contacts you to agree the date, time and fees.');
  if(/phone|contact|call|whatsapp|email/i.test(q))replies.push('Main telephone: +1 876 669 5974. WhatsApp: +1 876 291 4054. General email: hcmcstjames@gmail.com. Please keep medical details for your consultation.');
  if(/staff|tec|portal|login/i.test(q))replies.push('The Staff portal on the home page links to TEC Healthcare. Sign in there with your existing staff credentials. This guide cannot access patient records or reset accounts.');
  if(/health|wellness|news|blog|food|exerci|mental|diet/i.test(q))replies.push('Visit the Health hub for official Ministry resources, the Clinic blog for introductory articles, Health news for source-linked updates, or Local services for the St James directory.');
  return replies.length?replies.join('\n\n'):'I can help with opening hours, consultation fees, services, appointments and directions. For anything not covered in the published information, call +1 876 669 5974.';
 }
 async function ask(){const q=question.value.trim();if(!q)return;submit.disabled=true;mode.textContent='Checking your question…';
  try{if(aiReady&&checkbox.checked){const r=await fetch(api+'/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,consent:true,sessionId}),signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw new Error();answer.textContent=data.answer;mode.textContent=data.mode==='ai'?'AI-assisted answer · check important details with the clinic':'Clinic information · no AI answer used';}else{answer.textContent=guide(q);mode.textContent='Clinic guide · published information, not an AI-generated answer';}}
  catch{answer.textContent=guide(q);mode.textContent='AI is unavailable. Showing the clinic guide instead.';}finally{submit.disabled=false;}}
 form.addEventListener('submit',e=>{e.preventDefault();ask();});panel.querySelectorAll('.assistant-chips button').forEach(b=>b.addEventListener('click',()=>{question.value=b.textContent;ask();}));
})();
